  "investigate": [
    {
      "tool": "logs",
      "service": "workflow",
      "level": "WARN",
      "contains": "callback",
      "why": "callback_due is null for all stuck approvals — look for warnings about the callback endpoint registration failing silently after the v1.1 migration"
    }
  ],
  "hypotheses": [
    {
      "service": "workflow",
      "kind": "bad_deploy",
      "mechanism": "The v1.1 deploy at t=521 broke the supplier callback endpoint migration so that approval rows are inserted with callback_due=null, meaning the supplier is never properly notified or the callback deadline is never scheduled, leaving all approvals permanently unresolved.",
      "supporting": ["E1", "E3", "E4", "E8"],
      "refuting": ["E9"],
      "explains": ["I4_workflow_progress"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "workflow"}},
        {"action": "rerequest_supplier_approvals", "params": {}}
      ]
    }
  ],
  "summary": "The workflow v1.1 deploy at t=521 broke supplier callback registration, producing approval rows with null callback_due immediately after deploy, stalling 9 paid orders awaiting supplier approval."
}
```
